// 3. 키워드 트리거 로어 스캐너 (인물/고유명사/세계관/복선/허브 전방위 심층 추출)
const extraLoreRaw = inputs['📚 추가 로어북 (선택)'] || inputs['in_lore'] || [];
const allLorebookEntries = [];

function extractLorebooks(item) {
  if (!item) return;
  if (Array.isArray(item)) {
    item.forEach(extractLorebooks);
  } else if (typeof item === 'object') {
    if (item.keys && item.content) {
      allLorebookEntries.push(item);
    } else if (item.lorebook_entries && Array.isArray(item.lorebook_entries)) {
      item.lorebook_entries.forEach(extractLorebooks);
    } else {
      Object.values(item).forEach(v => {
