      });
    }
  }
}

charactersList.forEach(c => {
  if (Array.isArray(c.lorebook_entries)) allLorebookEntries.push(...c.lorebook_entries);
});
extractLorebooks(extraLoreRaw);

function scanTriggeredLores(text) {
  const matched = [];
  const lowerText = text.toLowerCase();
  for (const entry of allLorebookEntries) {
    if (!entry.keys || !entry.content) continue;
    const isHit = entry.keys.some(k => k && lowerText.includes(k.toLowerCase()));
    if (isHit) matched.push(`[${entry.title || entry.id}]: ${entry.content}`);
  }
  return Array.from(new Set(matched));
}

// 4. 독립된 캐릭터 에이전트 클래스
class CharacterAgent {
  constructor(charData, aiEnv) {
    this.name = charData.name;
    this.role = charData.role;
    this.persona_md = charData.persona_md;
    this.lorebook = charData.lorebook_entries || [];
    this.aiEnv = aiEnv;
  }

  // 턴 생성 (100% 실시간 LLM 호출)
  async actTurn(turnIndex, sceneText, visibleHistory, triggeredLores, dirNotes, otherAgents, fmtTemplate) {
    const target = otherAgents[0] || { name: '상대방' };

    const systemPrompt = `${this.persona_md}

# [현재 씬 상황 및 대화 목표]
${sceneText}
${dirNotes ? `\n[공통 연출 지침]: ${dirNotes}` : ''}
${triggeredLores.length > 0 ? `\n[대화 중 감지된 배경 로어 지식]:\n${triggeredLores.join('\n')}` : ''}

# [대본 출력 양식 지침]
${fmtTemplate || `너는 "${this.name}"이다. 상대의 말에 반응하여 (행동), [속마음], "대사" 양식을 엄수하여 이번 1턴만 작성하라.`}`;

    const userPrompt = `[직전까지의 대화 및 행동 기록]:\n${visibleHistory || '(대화 시작)'}\n\n너는 "${this.name}"(${this.role})이다. 상대방(${target.name})에게 반응하여 다음 1턴을 작성하라.`;

    const reply = await window.aiApi.call(this.aiEnv, systemPrompt, userPrompt);

    // 정규식 스마트 파싱
    const actionMatch = reply.match(/\(([^)]+)\)/);
    const thoughtMatch = reply.match(/\[속마음:?([^\]]+)\]|\[([^\]]+)\]/);
    const speechMatch = reply.match(/"([^"]+)"|“([^”]+)”/);

    return {
      action: actionMatch ? actionMatch[1].trim() : '',
      thought: thoughtMatch ? (thoughtMatch[1] || thoughtMatch[2]).replace(/^속마음:?\s*/, '').trim() : '',
      speech: speechMatch ? (speechMatch[1] || speechMatch[2]).trim() : reply.replace(/\([^)]+\)|\[[^\]]+\]/g, '').trim()
    };
  }
}

// 5. 에이전트 인스턴스 N개 동적 생성
const agents = charactersList.map(c => new CharacterAgent(c, aiConfig));

// 6. 다자간 핑퐁 대본 생성 루프
const turnsLog = [];

for (let turn = 1; turn <= totalTurns; turn++) {
  const currentAgent = agents[(turn - 1) % agents.length];
  const otherAgents = agents.filter(a => a.name !== currentAgent.name);

  // 상대방 속마음 가리기 필터링 적용
  const visibleHistoryForCurrent = turnsLog.map(item => {
    if (item.speaker === currentAgent.name) {
      return `${item.speaker}:\n(${item.action})\n[속마음: ${item.thought}]\n${item.speech}`;
    } else {
      return `${item.speaker}:\n(${item.action})\n${item.speech}`;
    }
  }).join('\n\n');

  // 키워드 로어 스캔
  const triggeredLores = scanTriggeredLores(visibleHistoryForCurrent + '\n' + sceneContext);

  // 이번 턴 에이전트 연기 수행
  const turnResult = await currentAgent.actTurn(
    turn,
    sceneContext,
    visibleHistoryForCurrent,
    triggeredLores,
    directorNotes,
    otherAgents,
    formatTemplate
  );

  turnsLog.push({
    turn: turn,
    speaker: currentAgent.name,
    role: currentAgent.role,
    action: turnResult.action,
    thought: turnResult.thought,
    speech: turnResult.speech
  });
}

