// 2. 위젯 설정 및 병합 모드 처리
const mergeMode = (input.merge_mode || '📌 스마트 섹션 마크다운 (제목 + 내용 자동 구분)').trim();
const prefix = (input.custom_prefix || '').trim();

let mergedText = '';
const textBlocks = [];

if (prefix) {
  textBlocks.push(prefix);
