} else if (mergeMode.includes('단순 줄바꿈')) {
  collectedItems.forEach(it => textBlocks.push(it.text));
  mergedText = textBlocks.join('\n\n');
} else if (mergeMode.includes('JSON')) {
  const jsonArr = collectedItems.map(it => it.raw);
  mergedText = JSON.stringify(jsonArr, null, 2);
} else {
  collectedItems.forEach(it => textBlocks.push(`### ${it.title}\n${it.text}`));
  mergedText = textBlocks.join('\n\n');
}

// 중복 로어북 제거
const uniqueLorebooks = [];
const seenLoreIds = new Set();
collectedLorebooks.forEach(lb => {
  if (lb && lb.id && !seenLoreIds.has(lb.id)) {
    seenLoreIds.add(lb.id);
    uniqueLorebooks.push(lb);
  } else if (lb && !lb.id) {
    uniqueLorebooks.push(lb);
  }
});

// 3. 최종 출력 반환
return {
  '📜 통합된 텍스트 / 마크다운': mergedText,
  '🧬 통합된 데이터 (JSON / 배열)': {
    count: collectedItems.length,
    lorebook_entries: uniqueLorebooks,
    items: collectedItems.map(it => it.raw),
    structured: collectedItems
  }
};
